package com.cowave.search.inbound_adapter.legacy.config

import com.cowave.search.application.index.service.LegacyReserveSyncApplicationService
import com.cowave.search.inbound_adapter.legacy.listener.LegacyReserveSyncListener
import org.apache.avro.specific.SpecificRecord
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty
import org.springframework.context.annotation.Bean
import org.springframework.context.annotation.Configuration
import org.springframework.kafka.listener.ConcurrentMessageListenerContainer

@Configuration
@ConditionalOnProperty(name = ["legacy-sync.enabled"], havingValue = "true", matchIfMissing = true)
class LegacyReserveSyncConfig(
    private val legacyReserveSyncConsumerProperties: LegacyReserveSyncConsumerProperties,
    private val legacyReserveSyncApplicationService: LegacyReserveSyncApplicationService,
) {
    @Bean
    fun legacyReserveSyncKafkaListenerContainer(): ConcurrentMessageListenerContainer<SpecificRecord, SpecificRecord> {
        val listener =
            LegacyReserveSyncListener(
                legacyReserveSyncApplicationService = legacyReserveSyncApplicationService,
            )
        return LegacyReserveSyncContainerFactory.createCdcContainer(
            dynamicIndexConsumer = legacyReserveSyncConsumerProperties.productCdc,
            listener = listener,
        )
    }
}

