package com.cowave.search.inbound_adapter.legacy.producer

import com.commerce.proxy.shopping.product.infrastructure.consumer.dto.Product
import com.commerce.proxy.shopping.product.infrastructure.consumer.dto.ProductCdcEnvelope
import com.commerce.proxy.shopping.product.infrastructure.consumer.dto.ProductCdcKey
import io.confluent.kafka.serializers.KafkaAvroSerializer
import io.confluent.kafka.serializers.KafkaAvroSerializerConfig
import org.apache.kafka.clients.producer.KafkaProducer
import org.apache.kafka.clients.producer.ProducerConfig
import org.apache.kafka.clients.producer.ProducerRecord
import java.util.Properties

/**
 * 로컬 Kafka에 테스트 Product CDC 메시지를 발행하는 유틸리티.
 *
 * - 정상 케이스 (categoryId 존재): 100건
 * - 문제 케이스 (categoryId null): 100건
 *
 * 실행 전 `docker compose up -d` 로 Kafka + Schema Registry 기동 필요.
 * IntelliJ에서 main 함수 좌측 ▶ 버튼으로 실행.
 */
private const val BOOTSTRAP_SERVERS = "localhost:9092"
private const val SCHEMA_REGISTRY_URL = "http://localhost:8081"
private const val TOPIC = "cmn.pricecompare-be-team.cdc.mongo.shopping.products.v1"

private const val NORMAL_COUNT = 100
private const val NULL_CATEGORY_COUNT = 100

fun main() {
    val producer = createProducer()

    producer.use { p ->
        // 1) 정상 케이스: categoryId 1~1000
        println("=== 정상 케이스 ${NORMAL_COUNT}건 발행 시작 ===")
        repeat(NORMAL_COUNT) { i ->
            val id = (i + 1).toLong()
            val categoryId = (i % 1000) + 1
            val record = buildProducerRecord(id, buildProduct(id, categoryId = categoryId))
            p.send(record) { metadata, ex ->
                if (ex != null) {
                    println("[ERROR] id=$id: ${ex.message}")
                } else {
                    println("[정상] id=$id, categoryId=$categoryId → partition=${metadata.partition()}, offset=${metadata.offset()}")
                }
            }
        }

        // 2) 문제 케이스: categoryId null
        println("\n=== 문제 케이스 (categoryId=null) ${NULL_CATEGORY_COUNT}건 발행 시작 ===")
        repeat(NULL_CATEGORY_COUNT) { i ->
            val id = (NORMAL_COUNT + i + 1).toLong()
            val record = buildProducerRecord(id, buildProduct(id, categoryId = null))
            p.send(record) { metadata, ex ->
                if (ex != null) {
                    println("[ERROR] id=$id: ${ex.message}")
                } else {
                    println("[문제] id=$id, categoryId=null → partition=${metadata.partition()}, offset=${metadata.offset()}")
                }
            }
        }

        p.flush()
        println("\n=== 총 ${NORMAL_COUNT + NULL_CATEGORY_COUNT}건 발행 완료 ===")
    }
}

private fun createProducer(): KafkaProducer<ProductCdcKey, ProductCdcEnvelope> {
    val props = Properties().apply {
        put(ProducerConfig.BOOTSTRAP_SERVERS_CONFIG, BOOTSTRAP_SERVERS)
        put(ProducerConfig.KEY_SERIALIZER_CLASS_CONFIG, KafkaAvroSerializer::class.java.name)
        put(ProducerConfig.VALUE_SERIALIZER_CLASS_CONFIG, KafkaAvroSerializer::class.java.name)
        put(KafkaAvroSerializerConfig.SCHEMA_REGISTRY_URL_CONFIG, SCHEMA_REGISTRY_URL)
        put(KafkaAvroSerializerConfig.AUTO_REGISTER_SCHEMAS, true)
    }
    return KafkaProducer(props)
}

private fun buildProduct(id: Long, categoryId: Int?): Product =
    Product.newBuilder()
        .setId$1(id)
        .setMallId(1)
        .setMallProductId("MALL-PROD-$id")
        .setName("테스트 상품 $id")
        .setCategoryId(categoryId)
        .setHasStock(true)
        .setCollectedStatus("ACTIVE")
